/**
 * Authoritative workspace version bumper.
 *
 * This is the ONLY supported way to move the whole workspace to one version. It
 * rewrites the `version` field of the root package.json and of every package
 * under the `packages/` directory, preserving key order and 2-space indentation.
 * It never touches dependencies, the pnpm lockfile, or generated artifacts —
 * those are regenerated by the offline SBOM / build-info generators and
 * `pnpm install`, never hand-edited.
 *
 * It does NOT commit, tag, sign, notarize, or publish. It also does not bless a
 * stable release: see `version-check.ts` for the `--allow-1.0` admission gate.
 *
 * Usage:
 *   node scripts/release/bump-version.ts 1.0.0-rc.1
 *
 * Exit codes: 0 = every package.json now carries the given version;
 * 1 = invalid version argument or a package.json without a `version` field.
 */

import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import path from "node:path";

export interface BumpChange {
  file: string;
  oldVersion: string | null;
  newVersion: string;
}

/** The same semver shape version-check.ts accepts: core triple plus optional prerelease/build suffix. */
export function isValidReleaseVersion(version: string): boolean {
  return /^\d+\.\d+\.\d+([-][0-9A-Za-z.-]+)?$/.test(version);
}

/** True for prerelease versions such as 1.0.0-rc.1; false for stable 1.0.0. */
export function isPrereleaseVersion(version: string): boolean {
  return isValidReleaseVersion(version) && version.includes("-");
}

/** Read a package.json as a plain object, preserving key order. */
export function readPackageJson(file: string): Record<string, unknown> {
  return JSON.parse(readFileSync(file, "utf8")) as Record<string, unknown>;
}

/** Write back with the repository's canonical 2-space formatting + trailing newline. */
export function writePackageJson(file: string, json: Record<string, unknown>): void {
  writeFileSync(file, JSON.stringify(json, null, 2) + "\n", "utf8");
}

/**
 * List every package.json this bumper owns: the root plus one per packages/*
 * directory. The lockfile is intentionally NOT here — pnpm regenerates it.
 */
export function bumpablePackageJsonFiles(root: string): string[] {
  const files = [path.join(root, "package.json")];
  const packagesDir = path.join(root, "packages");
  if (existsSync(packagesDir)) {
    for (const entry of readdirSync(packagesDir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const pkgFile = path.join(packagesDir, entry.name, "package.json");
      if (existsSync(pkgFile)) files.push(pkgFile);
    }
  }
  return files.sort();
}

/**
 * Rewrite the `version` field of every owned package.json. Pure bookkeeping:
 * dependencies, workspace links, and all other fields are byte-preserved except
 * the version string itself. Returns the per-file before/after record.
 */
export function bumpWorkspace(root: string, version: string): BumpChange[] {
  if (!isValidReleaseVersion(version)) {
    throw new Error(`invalid release version "${version}": expected semver like 1.0.0 or 1.0.0-rc.1`);
  }
  const changes: BumpChange[] = [];
  for (const file of bumpablePackageJsonFiles(root)) {
    const json = readPackageJson(file);
    const oldVersion = typeof json.version === "string" ? json.version : null;
    json.version = version;
    writePackageJson(file, json);
    changes.push({ file, oldVersion, newVersion: version });
  }
  return changes;
}

function repoRootFromArg(): string {
  return process.cwd();
}

function main(): void {
  const version = process.argv[2];
  if (!version) {
    process.stderr.write("usage: node scripts/release/bump-version.ts <version>  (e.g. 1.0.0-rc.1)\n");
    process.exit(1);
  }
  try {
    const changes = bumpWorkspace(repoRootFromArg(), version);
    const channel = isPrereleaseVersion(version) ? "prerelease/RC" : "stable";
    process.stdout.write(
      [
        `Bumped ${changes.length} package.json file(s) to ${version} (${channel}):`,
        ...changes.map((c) => `  ${path.relative(repoRootFromArg(), c.file)}: ${c.oldVersion ?? "(none)"} -> ${c.newVersion}`),
        "No lockfile, generated artifact, dependency, commit, tag, sign, notarize, or publish action was performed.",
        `Next: pnpm run release:all   (regenerates SBOM + build-info and re-checks readiness)`,
      ].join("\n") + "\n",
    );
  } catch (err) {
    process.stderr.write(`${(err as Error).message}\n`);
    process.exit(1);
  }
}

const invokedDirectly = process.argv[1] && process.argv[1].endsWith("bump-version.ts");
if (invokedDirectly) main();
